{
  "name": "Masterflex L/S 蠕动泵",
  "name_en": "Masterflex L/S Peristaltic Pump",
  "manufacturer": "Cole-Parmer",
  "description": "一款实验室蠕动泵，通过滚轮挤压软管实现液体输送，可连续运行或按设定转数运行，常用于试剂传输、循环、灌装和一般流体处理。",
  "description_en": "A laboratory peristaltic pump that moves liquid by compressing flexible tubing. It can run continuously or for a specified number of revolutions, and is commonly used for reagent transfer, recirculation, dispensing, and general fluid handling.",
  "tag_hints": [
    "peristaltic pump",
    "liquid transfer",
    "continuous pumping",
    "metered dispensing",
    "tubing pump",
    "fluid handling"
  ],
  "actions": [
    {
      "action_name": "auto-halt",
      "description": "立即停止泵的运行。",
      "description_en": "Halt the pump immediately."
    },
    {
      "action_name": "auto-run_continuously",
      "description": "以设定转速连续运行泵。",
      "description_en": "Run the pump continuously at the specified speed."
    },
    {
      "action_name": "auto-run_revolutions",
      "description": "按设定转数运行泵，用于定量输送液体。",
      "description_en": "Run the pump for a specified number of revolutions for metered liquid transfer."
    },
    {
      "action_name": "auto-send_command",
      "description": "向泵发送底层控制指令。",
      "description_en": "Send a low-level control command to the pump."
    },
    {
      "action_name": "auto-serialize",
      "description": "导出泵的当前配置或状态信息。",
      "description_en": "Export the pump's current configuration or state information."
    },
    {
      "action_name": "auto-setup",
      "description": "初始化并准备泵进行运行。",
      "description_en": "Initialize and prepare the pump for operation."
    },
    {
      "action_name": "auto-stop",
      "description": "停止泵的运行。",
      "description_en": "Stop the pump."
    }
  ]
}

